def baseline(grid, marker, maxgap=6):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
 for coords in ([[(r,c) for c in range(w)] for r in range(h)]+[[(r,c) for r in range(h)] for c in range(w)]):
  i=1
  while i<len(coords)-1:
   r,c=coords[i]
   if grid[r][c]==marker: i+=1; continue
   j=i
   while j<len(coords) and grid[coords[j][0]][coords[j][1]]!=marker: j+=1
   if j<len(coords) and j-i<=maxgap and grid[coords[i-1][0]][coords[i-1][1]]==marker and grid[coords[j][0]][coords[j][1]]==marker:
    for k in range(i,j): out[coords[k][0]][coords[k][1]]=2
   i=j
 return out

