def axis_filtered(grid,maxgap=6,strict_gap=2):
 from collections import Counter
 h,w=len(grid),len(grid[0]);counts=Counter(x for row in grid for x in row);marker=min(counts,key=counts.get);out=[row[:] for row in grid]
